import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易口義","description":"周易口義 - 周易口義","frontmatter":{"title":"周易口義","description":"周易口義 - 周易口義"},"headers":[],"relativePath":"classics/kouyi/001.md","filePath":"classics/kouyi/001.md"}'),r={name:"classics/kouyi/001.md"};function o(i,a,c,p,d,u){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易口義",tabindex:"-1"},[n("周易口義 "),e("a",{class:"header-anchor",href:"#周易口義","aria-label":"Permalink to “周易口義”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：周易口義十二卷，宋倪天隱述其師胡瑗之說也。瑗字翼之，泰州如皋人。用范仲淹薦，由布衣拜校書郎，歷太學博士，致仕歸。事蹟具宋史本傳。天隱始末未詳。葉祖洽作陳襄行狀，稱襄有二妹，一適進士倪天隱，殆即其人。董□嚴陵集載其桐廬縣令題名碑記一篇，意其嘗官睦州也。其說易以義理為宗。邵伯溫聞見前錄記程子與謝湜書，言讀易當先觀王弼、胡瑗、王安石三家。三原劉紹攽周易詳說曰：朱子謂程子之學源於周子，然考之易傳，無一語及太極。於觀卦彖辭雲：「予聞之胡翼之先生居上為天下之表儀。」於大畜上九雲：「予聞之胡先生曰：天之衢亨，誤加何字。」於夬九三雲：安定胡公移其文曰：「牡於𬱓，有兇，獨行遇雨，若濡有慍。君子夬夬，無咎。」於漸上九雲：安定胡公，以陸為逵。考伊川年譜稱皇祐中游太學，海陵胡翼之先生方主教導，得先生所試，大驚，即延見，處以學職，意其時必從而受業焉。世知其從事濂溪，不知其講易多本於翼之也。其說為前人所未及。今核以程傅良。然朱子語類亦稱「胡安定易分曉正當」，則是書在宋時固以義理說易之宗也。宋志載瑗易解十卷，周易口義十卷。朱彝尊經義考引李振裕之說雲：「瑗講授之餘，欲著述而未逮，其門人倪天隱述之，以非其師手著，故名曰口義。後世或稱口義，或稱易解，實無二書。」其說雖古無明文，今考晁公武讀書志亦云胡安定易傳，蓋門人倪天隱所纂，非其自著，故序首稱「先生曰」，其說與口義合，而列於易傳條下，亦不另出口義一條。然則易解、口義確為一書，宋志誤分為二明矣。乾隆四十三年三月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀周易口義發題",-1),e("p",null,"先生曰：夫易者，伏羲、文王、周公、孔子所以垂萬世之大法，三才變易之書也。自伏羲仰觀天文，俯察地理，始畫八卦。故爻有九、六，以盡陰陽之數；位有三畫，以盡三才之道；寫天、地、雷、風、水、火、山、澤之象，以盡天下之用；明、健、順、動、入、止、說、陷、明之體，以盡天下之理。然而伏羲之時，世質民淳，巧偽未興，詐端未作，故雖三畫，亦可以盡吉凶之變。自神農至堯、舜，莫不取法八卦之象，以為大治之本。歷夏沿商，以及桀、紂之世，民欲叢生，奸偽萬狀，禮隳樂缺，天下紛然。故三爻不能盡萬物之消長，究人心之情偽。文王有大聖之才，罹於憂患，觀紂之世，小人在位，詐偽日熾，思周身之防，達憂患之情，通天人之淵蘊，明人事之始終，遂重卦為六十四，重爻為三百八十四，又於逐卦之下為之彖辭。故天地通變之道，萬物情偽之理，一備於此。然謂之易者，按乾鑿度雲：「易一名而含三義：簡易也，不易也，變易也。」故穎達作疏，洎崔覲、劉正簡皆取其說。然謂不易、簡易者，於聖人之經，繆妄殆甚。且仲尼曰：「名不正則言不順，言不順則事不成。」是言凡興作之事，先須正名，名正則事方可成。況聖人作易，為萬世之大法，豈復有二三之義乎？按掦子曰：「陰不極則陽不生，亂不極則德不形。」又繫辭曰：",-1),e("p",null,"「易窮則變，變則通，通則久。」又云：「生生之謂易。」是大易之作，專取變易之義。蓋變易之道，天人之理也。以天道言之，則陰陽變易而成萬物，寒暑變易而成四時，日月變易而成晝夜。以人事言之，則得失變易而成吉凶，情偽變易而成利害，君子小人變易而成治亂。故天之變易，則歸乎生成，而自為常道；若人事變易，則固在上位者裁製之如何耳。何則？在位之人，苟知其君子小人相易而為治亂，則當常進用君子，而擯斥小人，則天下常治而無亂矣。知其情偽相易而成利害，當純用情實而黜去詐偽，則所為常利而無害矣。知其得失相易而成吉凶，當就事之得，而去事之失，則其行事常吉而無兇矣。是皆人事變易，不可不慎也。故大易之作，專取變易之義。謂之周易者，自伏羲畫卦，文王重之，又從而為之彖辭，至周公又為之爻辭，仲尼又十翼之。數聖相繼，其道大備於周，故曰「周易」。謂之「上經」、「下經」者，自乾、坤至坎、離三十卦謂之上經，自鹹、恆至未濟三十四卦謂之下經。然則所以分上下二經者，以簡帙重大，故分之也。乾、坤者，天地之象；坎、離者，日月之象，故取以為上經。鹹、恆者，夫婦之義；既濟、未濟，人倫終始之道，故取以為下經。先儒亦常謂不分之即無損於義，分之亦無害其實，但以簡帙重大而分之也。乾傳者，乾，卦名也；傳，傳也。言傳述聖人之法，以示萬世也。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
